#!/usr/bin/env python3
#
# tools/gen_moddata_ld.py - place Pascal module data blocks at their
# original addresses (docs/design-per-process-data.md, sections 3 and 5)
#
# Generated by: Claude Opus 5.5
#
# Every MODULE_DATA_DEFINE / MODULE_DATA_DEFINE_INIT site in the kernel
# sources (arch/m68k/arch.h) puts one C object into its own input section
# `.moddata.<name>'.  This script finds those sites in the source text (the
# address there is a literal; the compiler has already asserted it equal to
# the block's MODULE_DATA_DECLARE, arch/arch.h) and writes the linker
# fragment that sau2.ld INCLUDEs: one output section per block at its
# address, with the RFC file offset `addr - load address + 0x0C' that
# sau2.ld uses for every other loaded section.
#
# Modes:
#
#   gen_moddata_ld.py -o build/sau2/moddata.ld OBJ...
#       Scan the sources, read each block's size from its compiled object
#       (the object built from the defining .c must be among OBJ), check,
#       and write the fragment (only if its text changed).
#
#   gen_moddata_ld.py --check-only OBJ...
#       The same checks, no output.
#
#   gen_moddata_ld.py --check-elf build/sau2/moddata-check.elf
#       After a scratch link: every block symbol must sit at its declared
#       address with its section's size, inside no .text/.rodata/.data/.bss
#       range, and the sections must not overlap one another.
#
# Checks that fail the build:
#   - an address that is not a literal, or is odd;
#   - the same block name defined twice;
#   - two blocks overlapping (address ranges from the object sizes);
#   - a block below the RFC load address 0x00E00000, i.e. outside the
#     kernel image (static), or overlapping the linked text range
#     (.text/.rodata) - that one is only known after the link, so the
#     fragment carries an ld ASSERT for it and --check-elf re-checks it.

import argparse
import os
import re
import subprocess
import sys

RFC_LOAD_ADDR = 0x00E00000
RFC_HEADER_SIZE = 0x0C
KERNEL_VA_END = 0x01000000  # 24-bit physical/virtual space of the SAU2

SITE_RE = re.compile(
    r'\bMODULE_DATA_DEFINE(?:_INIT)?\s*\(\s*'
    r'(?P<type>[^,()]+?)\s*,\s*'
    r'(?P<name>[A-Za-z_][A-Za-z0-9_$]*)\s*,\s*'
    r'(?P<addr>[^,()]+?)\s*[,)]')

LITERAL_RE = re.compile(r'^(0[xX][0-9A-Fa-f]+|[0-9]+)[uUlL]*$')


class Block:
    def __init__(self, name, ctype, addr, src, line):
        self.name = name
        self.ctype = ctype
        self.addr = addr
        self.src = src
        self.line = line
        self.size = None

    @property
    def section(self):
        return '.moddata.' + self.name

    @property
    def where(self):
        return '%s:%d' % (self.src, self.line)


def fail(msgs):
    for m in msgs:
        print('gen_moddata_ld: error: ' + m, file=sys.stderr)
    sys.exit(1)


def strip_comments(text):
    # Keep newlines so line numbers survive; drop the comment bodies so a
    # macro name quoted in prose is not taken for a site.
    def blank(m):
        return re.sub(r'[^\n]', ' ', m.group(0))
    text = re.sub(r'/\*.*?\*/', blank, text, flags=re.S)
    text = re.sub(r'//[^\n]*', blank, text)
    return text


def scan_sources(root):
    """All MODULE_DATA_DEFINE* sites in root/**/*.c, test programs excluded
    (they are host-only and never linked into the kernel)."""
    blocks = []
    errors = []
    for dirpath, dirnames, filenames in os.walk(root):
        rel_dir = os.path.relpath(dirpath, root)
        parts = [] if rel_dir == '.' else rel_dir.split(os.sep)
        # never descend into build output, and skip host test programs
        dirnames[:] = sorted(d for d in dirnames
                             if not (not parts and d in ('build', 'dist'))
                             and d != 'test')
        for fn in sorted(filenames):
            if not fn.endswith('.c'):
                continue
            path = os.path.join(dirpath, fn)
            rel = os.path.relpath(path, root)
            with open(path, encoding='latin-1') as f:
                text = strip_comments(f.read())
            for m in SITE_RE.finditer(text):
                line = text.count('\n', 0, m.start()) + 1
                addr_text = m.group('addr').strip()
                if not LITERAL_RE.match(addr_text):
                    errors.append('%s:%d: %s: address `%s\' is not a literal'
                                  % (rel, line, m.group('name'), addr_text))
                    continue
                addr = int(addr_text.rstrip('uUlL'), 0)
                blocks.append(Block(m.group('name'), m.group('type').strip(),
                                    addr, rel, line))
    return blocks, errors


def static_checks(blocks):
    errors = []
    seen = {}
    for b in blocks:
        if b.name in seen:
            errors.append('%s: %s already defined at %s'
                          % (b.where, b.name, seen[b.name].where))
        seen[b.name] = b
        if b.addr & 1:
            errors.append('%s: %s at 0x%08X is not even-aligned'
                          % (b.where, b.name, b.addr))
        if b.addr < RFC_LOAD_ADDR or b.addr >= KERNEL_VA_END:
            errors.append('%s: %s at 0x%08X is outside the kernel range '
                          '0x%08X..0x%08X' % (b.where, b.name, b.addr,
                                              RFC_LOAD_ADDR, KERNEL_VA_END))
    sized = sorted((b for b in blocks if b.size is not None),
                   key=lambda b: b.addr)
    for a, b in zip(sized, sized[1:]):
        if a.addr + a.size > b.addr:
            errors.append('%s (0x%08X..0x%08X, %s) overlaps %s '
                          '(0x%08X..0x%08X, %s)'
                          % (a.name, a.addr, a.addr + a.size, a.where,
                             b.name, b.addr, b.addr + b.size, b.where))
    return errors


def section_sizes(objdump, obj):
    """{section name: size} for one object file."""
    out = subprocess.run([objdump, '-h', obj], check=True,
                         capture_output=True, text=True).stdout
    sizes = {}
    for line in out.splitlines():
        f = line.split()
        if len(f) >= 3 and f[0].isdigit():
            sizes[f[1]] = int(f[2], 16)
    return sizes


def attach_sizes(blocks, objects, objdump, build_dir):
    errors = []
    by_src = {}
    for o in objects:
        rel = os.path.relpath(o, build_dir)
        by_src[os.path.splitext(rel)[0] + '.c'] = o
    for b in blocks:
        obj = by_src.get(b.src)
        if obj is None or not os.path.exists(obj):
            errors.append('%s: no object for %s among the link inputs'
                          % (b.where, b.src))
            continue
        sizes = section_sizes(objdump, obj)
        if b.section not in sizes:
            errors.append('%s: %s has no section %s (is the site inside '
                          'an #if?)' % (b.where, obj, b.section))
            continue
        b.size = sizes[b.section]
    return errors


def fragment(blocks):
    out = []
    out.append('/*')
    out.append(' * moddata.ld - GENERATED by tools/gen_moddata_ld.py from the')
    out.append(' * MODULE_DATA_DEFINE sites; do not edit.  INCLUDEd inside')
    out.append(' * SECTIONS by sau2.ld, after .rodata and before .data.')
    out.append(' *')
    out.append(' * One output section per Pascal module data block, at the')
    out.append(' * block\'s original address; the file offset follows sau2.ld\'s')
    out.append(' * rule for every loaded section, VMA - load address + 0x0C.')
    out.append(' */')
    out.append('')
    out.append('    _moddata_text_end = .;')
    for b in sorted(blocks, key=lambda b: b.addr):
        out.append('')
        out.append('    /* %s (%s): %s, 0x%X bytes, 0x%08X..0x%08X */'
                   % (b.name, b.ctype, b.where, b.size, b.addr,
                      b.addr + b.size))
        out.append('    "%s" 0x%08X : AT(0x%08X - _rfc_load_addr + 0x%02X) {'
                   % (b.section, b.addr, b.addr, RFC_HEADER_SIZE))
        out.append('        KEEP(*("%s"))' % b.section)
        out.append('    }')
        out.append('    ASSERT(ADDR("%s") >= _moddata_text_end,'
                   % b.section)
        out.append('           "moddata: %s overlaps the text range")'
                   % b.name)
        out.append('    ASSERT(SIZEOF("%s") == 0x%X,' % (b.section, b.size))
        out.append('           "moddata: %s changed size since generation")'
                   % b.name)
    out.append('')
    out.append('    /* .data and .bss continue above text and every block */')
    out.append('    . = MAX(., _moddata_text_end);')
    out.append('')
    return '\n'.join(out)


def elf_sections(objdump, elf):
    out = subprocess.run([objdump, '-h', elf], check=True,
                         capture_output=True, text=True).stdout
    secs = {}
    for line in out.splitlines():
        f = line.split()
        if len(f) >= 4 and f[0].isdigit():
            secs[f[1]] = (int(f[3], 16), int(f[2], 16))  # (vma, size)
    return secs


def elf_symbols(nm, elf):
    out = subprocess.run([nm, '-S', '--defined-only', elf], check=True,
                         capture_output=True, text=True).stdout
    syms = {}
    for line in out.splitlines():
        f = line.split()
        if len(f) == 4:
            syms[f[3]] = (int(f[0], 16), int(f[1], 16), line)
        elif len(f) == 3:
            syms[f[2]] = (int(f[0], 16), None, line)
    return syms


def check_elf(blocks, elf, nm, objdump):
    errors = []
    secs = elf_sections(objdump, elf)
    syms = elf_symbols(nm, elf)
    others = [(n, v, s) for n, (v, s) in secs.items()
              if n in ('.text', '.rodata', '.data', '.bss') and s]
    for b in sorted(blocks, key=lambda b: b.addr):
        sym = syms.get(b.name)
        if sym is None:
            errors.append('%s: %s is not in %s' % (b.where, b.name, elf))
            continue
        addr, size, line = sym
        print('  %s' % line)
        if addr != b.addr:
            errors.append('%s: %s linked at 0x%08X, declared 0x%08X'
                          % (b.where, b.name, addr, b.addr))
        sec = secs.get(b.section)
        if sec is None:
            errors.append('%s: no output section %s in %s'
                          % (b.where, b.section, elf))
            continue
        svma, ssize = sec
        if svma != b.addr:
            errors.append('%s: section %s at 0x%08X, declared 0x%08X'
                          % (b.where, b.section, svma, b.addr))
        if size is not None and size != ssize:
            errors.append('%s: %s is 0x%X bytes but its section is 0x%X'
                          % (b.where, b.name, size, ssize))
        for n, v, s in others:
            if svma < v + s and v < svma + ssize:
                errors.append('%s: %s (0x%08X..0x%08X) overlaps %s '
                              '(0x%08X..0x%08X)'
                              % (b.where, b.name, svma, svma + ssize,
                                 n, v, v + s))
        b.size = ssize
    errors += static_checks(blocks)
    return errors


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('-o', '--output', help='fragment to write')
    ap.add_argument('--check-only', action='store_true',
                    help='run the checks, write nothing')
    ap.add_argument('--check-elf', metavar='ELF',
                    help='verify placement in a linked ELF')
    ap.add_argument('--root', default='.',
                    help='source root (domain_os/), default .')
    ap.add_argument('--build-dir', default='build/sau2',
                    help='object directory mirroring the sources')
    ap.add_argument('--objdump', default='m68k-elf-objdump')
    ap.add_argument('--nm', default='m68k-elf-nm')
    ap.add_argument('objects', nargs='*')
    args = ap.parse_args()

    blocks, errors = scan_sources(args.root)
    if errors:
        fail(errors)

    if args.check_elf:
        errors = check_elf(blocks, args.check_elf, args.nm, args.objdump)
        if errors:
            fail(errors)
        print('gen_moddata_ld: %d block(s) placed as declared'
              % len(blocks))
        return

    errors = attach_sizes(blocks, args.objects, args.objdump,
                          args.build_dir)
    errors += static_checks(blocks)
    if errors:
        fail(errors)

    if args.check_only:
        print('gen_moddata_ld: %d block(s), checks passed' % len(blocks))
        return
    if not args.output:
        fail(['-o, --check-only or --check-elf is required'])

    text = fragment(blocks)
    try:
        with open(args.output) as f:
            if f.read() == text:
                # unchanged: refresh the timestamp so make is satisfied
                os.utime(args.output)
                return
    except FileNotFoundError:
        pass
    os.makedirs(os.path.dirname(args.output) or '.', exist_ok=True)
    with open(args.output, 'w') as f:
        f.write(text)


if __name__ == '__main__':
    main()
